class Solution {
public:
    int maxProduct(vector<int>& nums) {
        int res = nums[0];
        int curMin = 1, curMax = 1;
        for (int n : nums) {
            if (n < 0) swap(curMin, curMax);
            curMax = max(n, curMax * n);
            curMin = min(n, curMin * n);
            res = max(res, curMax);
        }
        return res;
    }
};

class Solution {
    public int maxProduct(int[] nums) {
        int res = nums[0];
        int curMin = 1, curMax = 1;
        for (int n : nums) {
            if (n < 0) {
                int tmp = curMin;
                curMin = curMax;
                curMax = tmp;
            }
            curMax = Math.max(n, curMax * n);
            curMin = Math.min(n, curMin * n);
            res = Math.max(res, curMax);
        }
        return res;
    }
}

var maxProduct = function(nums) {
    let res = nums[0];
    let curMin = 1, curMax = 1;
    for (const n of nums) {
        if (n < 0) {
            const tmp = curMin;
            curMin = curMax;
            curMax = tmp;
        }
        curMax = Math.max(n, curMax * n);
        curMin = Math.min(n, curMin * n);
        res = Math.max(res, curMax);
    }
    return res;
};
